function renderReadingVoices(){const available=!!window.speechSynthesis&&typeof window.SpeechSynthesisUtterance==='function';deviceVoices=available?availableSpeechVoices():[];const voices=deviceVoices.filter(v=>/^en(?:[-_]|$)/i.test(v.lang)).sort((a,b)=>a.lang.localeCompare(b.lang)||a.name.localeCompare(b.name));const selector=$('reading-voice');selector.replaceChildren();const auto=document.createElement('option');auto.value='';auto.textContent='Automatic · device default';selector.append(auto);const seen=new Set();for(const voice of voices){const id=voice.voiceURI||voice.name+'|'+voice.lang;if(seen.has(id))continue;seen.add(id);const option=document.createElement('option');option.value=id;option.textContent=voice.name+' · '+voice.lang+(voice.localService?' · on-device':' · device service');selector.append(option);}const saved=readingPreferences().voice;selector.value=voices.some(v=>(v.voiceURI||v.name+'|'+v.lang)===saved)?saved:'';selector.disabled=!available;for(const id of ['voice-preview','voice-read-current','speak-quote'])$(id).disabled=!available;studioText('voice-availability',!available?'Read aloud is unavailable in this browser. Try opening Motive in Safari or Chrome.':saved&&!selector.value?'Your saved voice is unavailable on this device. Automatic voice will be used.':voices.length?voices.length+' English voice'+(voices.length===1?' is':'s are')+' available. Preview one before choosing.':'Your device has not listed English voices yet. Automatic reading is still available; reopen this panel after voices load.');renderReadingControls();}
function saveReadingPreferences(){studioPrefs.speech={voice:$('reading-voice').value,rate:Number($('reading-rate').value),pitch:Number($('reading-pitch').value)};persist();renderReadingControls();}
