async function startSound(kind){const version=sessionAudioVersion;await stopSound();if(version!==sessionAudioVersion||kind==='off'||document.hidden||!sessionRun?.running)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){studioText('session-status','Ambient sound is unavailable here. The timer still works.');return;}const ctx=new Audio();soundContext=ctx;await ctx.resume();if(version!==sessionAudioVersion||soundContext!==ctx||document.hidden||!sessionRun?.running){if(soundContext===ctx)await stopSound();else if(ctx.state!=='closed')await ctx.close().catch(()=>{});return;}const gain=ctx.createGain();gain.gain.value=.06;if(typeof configureMotiveAmbience==='function')configureMotiveAmbience(gain,ctx);gain.connect(ctx.destination);if(['rain','air','wash'].includes(kind)){const buffer=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate);const samples=buffer.getChannelData(0);let last=0;for(let i=0;i<samples.length;i++){if(kind==='air')samples[i]=(Math.random()*2-1)*.25;else{const smoothing=kind==='wash'?.008:.03;last=(last+smoothing*(Math.random()*2-1))/(1+smoothing);samples[i]=last*(kind==='wash'?4:3);}}const source=ctx.createBufferSource();source.buffer=buffer;source.loop=true;source.connect(gain);source.start();}else{for(const hz of (kind==='low'?[98,147,196]:[174,261,348])){const oscillator=ctx.createOscillator();oscillator.frequency.value=hz;oscillator.type='sine';oscillator.connect(gain);oscillator.start();}}}
