async function startRecording(target){if(recording)throw Error('Stop the current recording first.');if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Voice recording needs a supported browser on HTTPS.');if(target==='journal'&&studioPrefs.vault&&!vaultKey)throw Error('Unlock your journal first.');const requestVersion=++mediaRequestVersion;const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(requestVersion!==mediaRequestVersion){stream.getTracks().forEach(t=>t.stop());throw Error('Recording canceled because you left the studio.');}recordingStream=stream;recordingTarget=target;recordingChunks=[];recording=new MediaRecorder(recordingStream);recording.ondataavailable=e=>{if(e.data.size)recordingChunks.push(e.data);};recording.onstop=async()=>{clearTimeout(recordingTimeout);const blob=new Blob(recordingChunks,{type:recording.mimeType});recording=null;recordingStream?.getTracks().forEach(t=>t.stop());recordingStream=null;$('record-stop').disabled=true;$('journal-record-stop').disabled=true;try{if(blob.size>8*1024*1024)throw Error('This recording is too large. Try a shorter one.');const audio=await fileData(blob);if(target==='journal'){pendingJournalAudio=audio;studioText('journal-attachment','Voice reflection ready. Tap Save this moment to keep it.');}else{await dbWrite([newRecord('voice',{title:$('recording-title').value.trim().slice(0,100)||'A personal reminder',audio,transcript:$('recording-script').value.trim().slice(0,6000)})]);studioText('record-status','Recording saved on this device.');renderVoices();}}catch(e){studioError(target==='journal'?'journal-status':'record-status',e);}};recording.start();recordingTimeout=setTimeout(()=>recording?.stop(),60000);$(target==='journal'?'journal-record-stop':'record-stop').disabled=false;studioText(target==='journal'?'journal-attachment':'record-status','Recording… tap Stop when you are ready (maximum 1 minute).');}
