async function renderJournal(){const sessionVersion=vaultSessionVersion;updatePrompt();$('journal-list').replaceChildren();$('studio-trends').replaceChildren();const days=Object.keys(state.companion.journal).filter(d=>state.companion.journal[d].mood).sort().slice(-7);for(const day of days){const li=document.createElement('li');const entry=state.companion.journal[day];li.textContent=`${day} · ${arrivalChoices[entry.mood]?.label||entry.mood}`;$('studio-trends').append(li);}if(!days.length){const li=document.createElement('li');li.textContent='Check in on the main screen to start your history.';$('studio-trends').append(li);}const locked=!!studioPrefs.vault&&!vaultKey;$('journal-editor').hidden=locked;$('vault-locked').hidden=!locked;if(locked)return;for(const [day,entry]of Object.entries(state.companion.journal).filter(([,e])=>e.note).sort(([a],[b])=>b.localeCompare(a))){const article=document.createElement('article');article.className='studio-record';const date=document.createElement('small');date.textContent=day+' · Earlier reflection';const note=document.createElement('p');note.textContent=entry.note;article.append(date,note);$('journal-list').append(article);}for(const row of studioRecords.filter(r=>r.kind==='journal'&&!r.deleted).sort((a,b)=>b.updated-a.updated).slice(0,30)){try{const payload=row.encrypted?await unseal(row.encrypted,vaultKey):row.payload;if(sessionVersion!==vaultSessionVersion||studioPrefs.vault&&!vaultKey)return;$('journal-list').append(recordElement(row,payload));}catch{studioText('journal-status','Some entries use another vault passphrase. Import them on the original device to read them.');}}}
