const baseUpdateBackground=updateQuoteBackground;
updateQuoteBackground=function(quote=current,changePicture=false){baseUpdateBackground(quote,changePicture);const row=state.background!=='none'&&studioRecords.find(r=>r.id==='quote-photo'&&!r.deleted);const video=state.background!=='none'&&studioRecords.find(r=>r.id==='quote-video'&&!r.deleted);const card=$('quote-card');if(row&&!video){displayedQuoteScene={key:'personal-'+row.updated,image:row.payload.image,label:'Your photo',meaning:'A personal background'};card.classList.add('has-scene');card.style.setProperty('--quote-scene',`url("${row.payload.image}")`);motivePrivateSceneCaption('Your personal photo · Change it in Wellbeing studio → Settings');studioText('scene-options-button','Your photo ▾');}if(video)motivePrivateSceneCaption('Your muted video · A still frame is used in downloads.');card.classList.toggle('has-motion',!!video&&!matchMedia('(prefers-reduced-motion: reduce)').matches);let element=$('quote-motion');if(video&&!matchMedia('(prefers-reduced-motion: reduce)').matches){if(!element){element=document.createElement('video');element.id='quote-motion';element.className='motive-motion';element.muted=true;element.loop=true;element.playsInline=true;element.setAttribute('aria-hidden','true');card.prepend(element);}if(element.dataset.version!==String(video.updated)){element.src=video.payload.video;element.dataset.version=String(video.updated);}element.play().catch(()=>toast('Tap the video background control again to allow playback.'));}else if(element){element.pause();element.remove();}if(video&&!matchMedia('(prefers-reduced-motion: reduce)').matches)watchQuotePhoto(null);else if(row&&!video)watchQuotePhoto(displayedQuoteScene);};
$('studio-photo').onchange=async()=>{try{const image=await imageData($('studio-photo').files[0]);await dbWrite([{id:'quote-photo',kind:'background',updated:Date.now(),payload:{image}},{id:'quote-video',kind:'background',updated:Date.now(),deleted:true}]);state.background='auto';persist();updateQuoteBackground();toast('Your photo is now behind your quotes.');}catch(e){toast(e.message);}$('studio-photo').value='';};
$('studio-video').onchange=async()=>{try{const file=$('studio-video').files[0];if(!file||!['video/mp4','video/webm'].includes(file.type)||file.size>12*1024*1024)throw Error('Choose an MP4 or WebM video smaller than 12 MB.');const video=await fileData(file);await dbWrite([{id:'quote-video',kind:'background',updated:Date.now(),payload:{video}}]);state.background='auto';persist();updateQuoteBackground();toast('Muted video added. Reduced Motion uses the still scene.');}catch(e){toast(e.message);}$('studio-video').value='';};
$('clear-studio-photo').onclick=async()=>{try{await dbWrite(['quote-photo','quote-video'].map(id=>({id,kind:'background',updated:Date.now(),deleted:true})));updateQuoteBackground();toast('Motive scenes restored.');}catch(e){toast(e.message);}};
const originalCanvas=createQuoteCanvas;
createQuoteCanvas=async function(quote,wallpaper=false){const video=$('quote-motion');const prior=displayedQuoteScene;if(video&&video.readyState>=2){const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;c.getContext('2d').drawImage(video,0,0);displayedQuoteScene={key:'video-frame-'+Date.now(),image:c.toDataURL('image/jpeg',.85)};}const frameKey=displayedQuoteScene?.key;try{return await originalCanvas(quote,wallpaper);}finally{if(frameKey?.startsWith('video-frame-'))quotePhotoCache.delete(frameKey);displayedQuoteScene=prior;}};
function renderVault(){const locked=studioPrefs.vault&&!vaultKey;$('vault-enable').disabled=!!studioPrefs.vault;$('vault-open').disabled=!locked;$('vault-close').disabled=!vaultKey;studioText('vault-status',studioPrefs.vault?(locked?'Journal locked.':'Journal unlocked for this visit.'):'Journal lock is off.');}
$('vault-enable').onclick=async()=>{const sessionVersion=vaultSessionVersion;const button=$('vault-enable');button.disabled=true;try{if(studioPrefs.vault)throw Error('Journal lock is already enabled.');const phrase=$('vault-password').value;const salt=crypto.getRandomValues(new Uint8Array(16));const key=await deriveKey(phrase,salt);const verifier=await seal({motive:'journal-v1'},key);const rows=[];for(const row of studioRecords.filter(r=>r.kind==='journal'&&r.payload&&!r.encrypted)){const encrypted=await seal(row.payload,key);rows.push({...row,encrypted,payload:undefined});}for(const [day,entry]of Object.entries(state.companion.journal)){if(entry.note){const row=newRecord('journal',{day,period:'Reflection',note:entry.note});row.encrypted=await seal(row.payload,key);delete row.payload;rows.push(row);}}await dbWrite([...rows,{id:'vault-config',kind:'vault',updated:Date.now(),payload:{salt:bytes64(salt),verifier}}]);studioPrefs.vault={salt:bytes64(salt),verifier};vaultKey=document.hidden||sessionVersion!==vaultSessionVersion?null:key;for(const entry of Object.values(state.companion.journal))entry.note='';persist();$('vault-password').value='';renderPersonalSpace();renderVault();await renderJournal();}catch(e){studioError('vault-status',e);if(!studioPrefs.vault)button.disabled=false;}};
$('vault-open').onclick=async()=>{const sessionVersion=vaultSessionVersion;try{const config=studioPrefs.vault;const key=await deriveKey($('vault-password').value,from64(config.salt));const check=await unseal(config.verifier,key);if(check.motive!=='journal-v1')throw Error('Invalid journal vault.');if(document.hidden||sessionVersion!==vaultSessionVersion)return;vaultKey=key;$('vault-password').value='';renderVault();await renderJournal();}catch(e){studioError('vault-status',e);}};
function lockJournal(){vaultSessionVersion++;vaultKey=null;$('vault-password').value='';$('studio-journal-note').value='';$('journal-photo').value='';pendingJournalAudio=null;studioText('journal-attachment','');$('journal-list').replaceChildren();$('journal-editor').hidden=!!studioPrefs.vault;$('vault-locked').hidden=!studioPrefs.vault;for(const audio of studioDialog.querySelectorAll('audio')){audio.pause();audio.removeAttribute('src');}renderVault();}
$('vault-close').onclick=()=>{lockJournal();renderJournal();};
// Existing reflection entry points now lead to the same journal, so new notes respect its lock.
$('reflection-button').addEventListener('click',()=>{$('reflection-dialog').close();openStudio('journal');});
function calendarFile(time){if(!/^\d{2}:\d{2}$/.test(time))throw Error('Choose a reminder time.');const date=dayKey().replaceAll('-','');return `BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Motive//Daily Pause//EN\r\nBEGIN:VEVENT\r\nUID:motive-daily-${crypto.randomUUID()}\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}\r\nDTSTART:${date}T${time.replace(':','')}00\r\nDURATION:PT5M\r\nRRULE:FREQ=DAILY\r\nSUMMARY:A little perspective from Motive\r\nDESCRIPTION:Open Motive for a quote or a gentle pause.\r\nURL:https://joewalker989.github.io/motive/\r\nBEGIN:VALARM\r\nTRIGGER:-PT0M\r\nACTION:DISPLAY\r\nDESCRIPTION:A moment for yourself\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`;}
$('calendar-reminder').onclick=()=>{try{downloadFile(new Blob([calendarFile($('reminder-time').value)],{type:'text/calendar'}),'motive-daily-pause.ics');studioText('reminder-status','Import the downloaded event in your calendar. Check its daily repeat and notification settings.');}catch(e){studioError('reminder-status',e);}};
$('foreground-reminder').onclick=async()=>{if(!('Notification'in window)){studioText('reminder-status','Browser notifications are unavailable here. Use the calendar reminder.');return;}try{const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notification permission was not granted. The calendar reminder is available.');studioPrefs.reminder=$('reminder-time').value;persist();studioText('reminder-status','Enabled while Motive is running. Closing the app stops these browser alerts.');}catch(e){studioError('reminder-status',e);}};
setInterval(()=>{const time=new Date().toTimeString().slice(0,5);if(studioPrefs.reminder===time&&studioPrefs.reminded!==dayKey()&&'Notification'in window&&Notification.permission==='granted'){try{new Notification('A little space for you',{body:'Open Motive for a kind reminder or a calming pause.',icon:'./icons/icon-192.png'});studioPrefs.reminded=dayKey();persist();}catch{studioText('reminder-status','This browser cannot send the alert. Use the calendar reminder.');}}},15000);
function safeMedia(value,type){const supported=type==='image/'?/^data:image\/(jpeg|png|webp);/:type==='audio/'?/^data:audio\/(webm|ogg|mp4|mpeg|wav|x-wav);/:/^data:video\/(mp4|webm);/;return supported.test(value)&&typeof value==='string'&&value.length<=18*1024*1024&&new RegExp('^data:'+type+'[a-zA-Z0-9.+-]+(?:;codecs=[a-zA-Z0-9., -]+)?;base64,[A-Za-z0-9+/=]+$').test(value);}
function validateStudioRows(rows){if(!Array.isArray(rows)||rows.length>30000)throw Error('Invalid studio records.');const ids=new Set();for(const r of rows){if(!r||typeof r.id!=='string'||r.id.length>120||ids.has(r.id)||!['journal','voice','vision','background','vault','habit','habit-log','mood','mood-label','quote-tags','narration','movement'].includes(r.kind)||!Number.isFinite(r.updated))throw Error('Invalid studio record.');ids.add(r.id);if(r.deleted&&!r.payload&&!r.encrypted)continue;if(r.encrypted){if(r.payload!==undefined||!['journal','voice','narration','vision'].includes(r.kind)||typeof r.encrypted.cipher!=='string'||r.encrypted.cipher.length>24*1024*1024||!/^[-A-Za-z0-9+/=]+$/.test(r.encrypted.cipher)||typeof r.encrypted.iv!=='string'||r.encrypted.iv.length!==16)throw Error('Invalid encrypted journal.');continue;}const p=r.payload;if(!p||typeof p!=='object')throw Error('Missing record content.');if(r.kind==='vault'&&p.protectedKinds!==undefined&&(!Array.isArray(p.protectedKinds)||p.protectedKinds.length>3||p.protectedKinds.some(k=>!['voice','narration','vision'].includes(k))))throw Error('Invalid protected media collections.');if(['voice','narration'].includes(r.kind)&&p.transcript!==undefined&&(typeof p.transcript!=='string'||p.transcript.length>6000))throw Error('Invalid recording transcript.');if(['habit','habit-log','mood','mood-label','quote-tags','narration','movement'].includes(r.kind))validateGrowthPayload(r);if(r.kind==='vault'&&(r.id!=='vault-config'||typeof p.salt!=='string'||p.salt.length!==24||typeof p.verifier?.iv!=='string'||p.verifier.iv.length!==16||typeof p.verifier?.cipher!=='string'||p.verifier.cipher.length>1024))throw Error('Invalid journal vault configuration.');for(const k of ['title','note','day','period'])if(p[k]!==undefined&&(typeof p[k]!=='string'||p[k].length>(k==='note'?4000:240)))throw Error('Invalid journal text.');if(p.image&&!safeMedia(p.image,'image/'))throw Error('Invalid photo in backup.');if(p.audio&&!safeMedia(p.audio,'audio/'))throw Error('Invalid recording in backup.');if(p.video&&!safeMedia(p.video,'video/'))throw Error('Invalid video in backup.');}return rows;}
async function fullStudioBackup(){return {app:'motive-studio',version:1,quoteBackup:backupData(),records:await dbRead(),exportedAt:new Date().toISOString()};}
function inspectStudioBackup(data){if(data?.app!=='motive-studio'||data.version!==1)throw Error('Choose a full Motive studio backup.');const rows=validateStudioRows(data.records);const merged=mergeBackup(data.quoteBackup);if(rows.some(r=>r.kind==='vault'&&!r.deleted)&&Object.values(merged.companion?.journal||{}).some(e=>e.note))throw Error('Import unlocked reflections before enabling a journal vault.');if(studioPrefs.vault&&rows.some(r=>r.kind==='journal'&&r.payload&&!r.encrypted))throw Error('This backup has unlocked journals. Import it before enabling journal lock, or unlock and encrypt it on the original device.');const incomingVault=rows.find(r=>r.id==='vault-config'&&!r.deleted);if(studioPrefs.vault&&incomingVault&&incomingVault.payload.salt!==studioPrefs.vault.salt)throw Error('This backup belongs to a different journal vault. Keep it separate to avoid losing access.');return {rows,merged,incomingVault};}
async function importStudioBackup(data){studioRecords=await dbRead();const {rows,merged,incomingVault}=inspectStudioBackup(data);remapGrowthTags(rows,data.quoteBackup,merged);await dbWrite(WB.mergeRecords(studioRecords,rows));Object.assign(state,merged);refreshStudioPreferences();if(typeof renderMotiveHome==='function')renderMotiveHome();if(typeof renderMotivePreferences==='function')renderMotivePreferences();if(typeof renderMotiveAudio==='function')renderMotiveAudio();if(typeof renderMotivePractice==='function')renderMotivePractice();if(typeof renderMotiveAccess==='function')renderMotiveAccess();if(!studioPrefs.vault&&incomingVault)studioPrefs.vault=incomingVault.payload;persist();renderVault();collectionOptions();renderCollection();updateSave();updateGreeting();renderPersonalSpace();updateQuoteBackground();}
$('studio-export').onclick=async()=>{try{downloadFile(new Blob([JSON.stringify(await fullStudioBackup())],{type:'application/json'}),`motive-complete-${dayKey()}.json`);studioText('studio-backup-status','Full backup downloaded, including photos, recordings, and journal records.');}catch(e){studioError('studio-backup-status',e);}};
$('studio-import').onchange=async()=>{try{const file=$('studio-import').files[0];if(!file)return;if(typeof previewMotiveBackup==='function'){await previewMotiveBackup(file,true);return;}if(file.size>100*1024*1024)throw Error('Choose a backup smaller than 100 MB.');await importStudioBackup(JSON.parse(await file.text()));studioText('studio-backup-status','Backup merged. Existing quotes and studio records were kept.');}catch(e){studioError('studio-backup-status',e);}$('studio-import').value='';};
async function syncStudio(){if(!syncSecrets||syncBusy||document.hidden)return;syncBusy=true;try{const {url,phrase,user,password}=syncSecrets;const headers={};if(user||password)headers.Authorization='Basic '+bytes64(new TextEncoder().encode(user+':'+password));const response=await fetch(url,{headers,credentials:'omit',redirect:'error',signal:AbortSignal.timeout(20000),cache:'no-store'});let etag=null;if(response.ok){etag=response.headers.get('ETag');if(!etag)throw Error('Your sync server must expose an ETag header to avoid overwriting other devices.');const data=await response.json();if(data.app!=='motive-encrypted-sync'||typeof data.salt!=='string')throw Error('This URL does not contain a Motive sync backup.');const key=await deriveKey(phrase,from64(data.salt));await importStudioBackup(await unseal(data,key));}else if(response.status!==404)throw Error('Could not read your sync file. Check server access and CORS settings.');const salt=crypto.getRandomValues(new Uint8Array(16));const key=await deriveKey(phrase,salt);const sealed=await seal(await fullStudioBackup(),key);const body=JSON.stringify({app:'motive-encrypted-sync',salt:bytes64(salt),...sealed});const put=await fetch(url,{method:'PUT',headers:{...headers,'Content-Type':'application/json',...(etag?{'If-Match':etag}:{'If-None-Match':'*'})},body,credentials:'omit',redirect:'error',signal:AbortSignal.timeout(20000)});if(put.status===412)throw Error('Another device updated the file. Sync again to merge its latest changes.');if(!put.ok)throw Error('Could not save to your sync server. Your local data is kept.');studioText('sync-status','Encrypted sync complete · '+new Date().toLocaleTimeString());}catch(e){studioError('sync-status',e);}finally{syncBusy=false;}}
$('sync-connect').onclick=()=>{try{const url=new URL($('sync-url').value);if(url.protocol!=='https:'||url.username||url.password||url.hash)throw Error('Use an HTTPS file URL without embedded credentials or a fragment.');if($('sync-phrase').value.length<10)throw Error('Use a shared encryption passphrase of at least 10 characters.');syncSecrets={url:url.href,phrase:$('sync-phrase').value,user:$('sync-user').value,password:$('sync-password').value};$('sync-phrase').value='';$('sync-password').value='';clearInterval(syncTimer);if($('sync-auto').checked)syncTimer=setInterval(syncStudio,60000);syncStudio();}catch(e){studioError('sync-status',e);}};
$('sync-disconnect').onclick=()=>{syncSecrets=null;clearInterval(syncTimer);syncTimer=null;studioText('sync-status','Disconnected. Credentials removed from this session.');};
studioDialog.addEventListener('close',()=>{mediaRequestVersion++;pauseSession();stopSpeech();if(recording?.state==='recording')recording.stop();for(const audio of studioDialog.querySelectorAll('audio'))audio.pause();if(studioPrefs.vault)lockJournal();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){mediaRequestVersion++;pauseSession();stopSpeech();$('quote-motion')?.pause();if(recording?.state==='recording')recording.stop();if(studioPrefs.vault)lockJournal();}else{updateQuoteBackground();if(syncSecrets)syncStudio();}});
dbRead().then(rows=>{studioRecords=rows;const config=rows.find(r=>r.id==='vault-config'&&!r.deleted);if(config&&!studioPrefs.vault){studioPrefs.vault=config.payload;persist();}updateQuoteBackground();}).catch(()=>{});
renderLanguage();renderDesign();renderJourney();renderVault();

const studioBackupHelp=document.createElement('p');studioBackupHelp.className='studio-note';studioBackupHelp.textContent='Journal entries, photos and recordings need the full backup in Wellbeing studio → Settings.';$('backup-button').parentElement.after(studioBackupHelp);
